// Calcula y pinta el % de películas vistas dentro de una colección
function actualizarProgresoColeccion(colId) {
    const grilla = document.getElementById(`grilla-${colId}`);
    if (!grilla) return;
    const total = grilla.children.length;
    const vistas = grilla.querySelectorAll('.tarjeta-media.vista').length;
    const porcentaje = total > 0 ? Math.round((vistas / total) * 100) : 0;

    const fill = document.getElementById(`barra-${colId}-fill`);
    const texto = document.getElementById(`barra-${colId}-texto`);
    if (fill) fill.style.width = porcentaje + '%';
    if (texto) texto.textContent = porcentaje + '% completado (' + vistas + '/' + total + ')';
}

// Igual que arriba, pero para fichas "carpeta" cuyo contenido no vive en
// col.peliculas sino repartido en listaMedia bajo una misma categoría
// (ej: Leonardo DiCaprio, Disney Animation)
// ==========================================
// FILTRO POR EDITORIAL (combinado con el de personaje/tanda)
// ==========================================
// Aplica en conjunto el filtro de personaje/año YA activo en la sección más el
// de editorial: una tarjeta se muestra solo si pasa las DOS condiciones.
// No reemplaza al filtro de personaje existente, lo restringe más.
// ==========================================
// FILTRO "TODO / PELÍCULAS / SERIES" (combinado con el de década, para
// fichas de Actores). Reutilizable para cualquier actor: solo hace falta
// agregar la fila de botones en el HTML e inicializarla una vez.
// ==========================================
function aplicarFiltroTipoYDecadaActor(seccionId, claseBotonesDecada) {
    const seccion = document.getElementById(seccionId);
    if (!seccion) return;
    const botonDecadaActivo = seccion.querySelector(`.${claseBotonesDecada}.activo`);
    const decadaElegida = botonDecadaActivo ? botonDecadaActivo.getAttribute('data-tipo') : null;
    const botonTipoActivo = seccion.querySelector('.btn-filtro-tipo-actor.activo');
    const tipoElegido = botonTipoActivo ? botonTipoActivo.getAttribute('data-tipo-medio') : 'todo';

    seccion.querySelectorAll('.tarjeta-media').forEach(tarjeta => {
        const coincideDecada = !decadaElegida || tarjeta.getAttribute('data-subtipo') === decadaElegida;
        const etiquetaTipo = tarjeta.querySelector('p') ? tarjeta.querySelector('p').textContent : '';
        const coincideTipo = tipoElegido === 'todo'
            || (tipoElegido === 'pelis' && etiquetaTipo === 'Película')
            || (tipoElegido === 'series' && etiquetaTipo === 'Serie');
        tarjeta.style.display = (coincideDecada && coincideTipo) ? 'flex' : 'none';
    });
}

function inicializarFiltroTipoActor(seccionId, claseBotonesDecada) {
    const seccion = document.getElementById(seccionId);
    if (!seccion) return;
    seccion.querySelectorAll('.btn-filtro-tipo-actor').forEach(boton => {
        boton.addEventListener('click', function() {
            seccion.querySelectorAll('.btn-filtro-tipo-actor').forEach(b => b.classList.remove('activo'));
            this.classList.add('activo');
            aplicarFiltroTipoYDecadaActor(seccionId, claseBotonesDecada);
        });
    });
}

function aplicarFiltroComicCombinado(seccionId, claseBotonesPersonaje, atributoPersonajeTarjeta) {
    const botonPersonajeActivo = document.querySelector(`.${claseBotonesPersonaje}.activo`);
    const tipoElegido = botonPersonajeActivo ? botonPersonajeActivo.getAttribute('data-tipo') : 'todos';
    const filaEditorial = document.getElementById(`filtro-editorial-${seccionId}`);
    const botonEditorialActivo = filaEditorial ? filaEditorial.querySelector('.btn-filtro-editorial-comic.activo') : null;
    const editorialElegida = botonEditorialActivo ? botonEditorialActivo.getAttribute('data-editorial') : 'todos';

    const tarjetas = document.querySelectorAll(`#${seccionId} .tarjeta-media`);
    tarjetas.forEach(tarjeta => {
        const etiquetas = (tarjeta.getAttribute(atributoPersonajeTarjeta) || '').split(',');
        const coincidePersonaje = tipoElegido === 'todos' || etiquetas.includes(tipoElegido);
        const coincideEditorial = editorialElegida === 'todos' || tarjeta.getAttribute('data-editorial') === editorialElegida;
        tarjeta.style.display = (coincidePersonaje && coincideEditorial) ? 'flex' : 'none';
    });
}

// Crea la fila de botones de editorial dentro de una sección (si su HTML ya
// trae el contenedor #filtro-editorial-<seccionId> vacío) y le conecta el click.
function inicializarFiltroEditorial(seccionId, claseBotonesPersonaje, atributoPersonajeTarjeta) {
    const fila = document.getElementById(`filtro-editorial-${seccionId}`);
    if (!fila) return;
    const botones = fila.querySelectorAll('.btn-filtro-editorial-comic');
    botones.forEach(boton => {
        boton.addEventListener('click', function() {
            botones.forEach(b => b.classList.remove('activo'));
            this.classList.add('activo');
            aplicarFiltroComicCombinado(seccionId, claseBotonesPersonaje, atributoPersonajeTarjeta);
        });
    });
}

function actualizarProgresoCategoria(colId, categoria) {
    const fill = document.getElementById(`barra-${colId}-fill`);
    const texto = document.getElementById(`barra-${colId}-texto`);
    if (!fill || !texto) return;
    const titulos = listaMedia.filter(i => i.categoria === categoria);
    const total = titulos.length;
    const vistas = titulos.filter(i => titulosVistosGuardados.has(i.titulo)).length;
    const porcentaje = total > 0 ? Math.round((vistas / total) * 100) : 0;
    fill.style.width = porcentaje + '%';
    texto.textContent = porcentaje + '% completado (' + vistas + '/' + total + ')';
}

// Para las colecciones "numeradas" (Marvel Excelsior, Must Have, Secret Wars,
// DC Colección Heroes y Villanos, etc.) cuyos ítems no comparten una única
// categoria (están repartidos en varias eras) pero sí un patrón de título
// reconocible ("Marvel Excelsior #N", etc.). excluirTexto permite descartar
// ediciones viejas/duplicadas que matchean el mismo patrón (como los ítems
// "(Ovni)" de Esenciales DC, que pertenecen a otra colección).
function actualizarProgresoPatron(colId, patronSource, excluirTexto) {
    const fill = document.getElementById(`barra-${colId}-fill`);
    const texto = document.getElementById(`barra-${colId}-texto`);
    if (!fill || !texto) return;
    const regex = new RegExp(patronSource, 'i');
    const titulos = listaMedia.filter(i => regex.test(i.titulo) && (!excluirTexto || !i.titulo.includes(excluirTexto)));
    const total = titulos.length;
    const vistas = titulos.filter(i => titulosVistosGuardados.has(i.titulo)).length;
    const porcentaje = total > 0 ? Math.round((vistas / total) * 100) : 0;
    fill.style.width = porcentaje + '%';
    texto.textContent = porcentaje + '% completado (' + vistas + '/' + total + ')';
}

// Igual que actualizarProgresoPatron, pero para las colecciones definidas
// con una lista fija de títulos (COLECCIONES_LISTA_FIJA).
function actualizarProgresoTitulos(colId, titulos) {
    const fill = document.getElementById(`barra-${colId}-fill`);
    const texto = document.getElementById(`barra-${colId}-texto`);
    if (!fill || !texto) return;
    const total = titulos.length;
    const vistas = titulos.filter(t => titulosVistosGuardados.has(t)).length;
    const porcentaje = total > 0 ? Math.round((vistas / total) * 100) : 0;
    fill.style.width = porcentaje + '%';
    texto.textContent = porcentaje + '% completado (' + vistas + '/' + total + ')';
}

function actualizarTodasLasColecciones() {
    colecciones.forEach(col => {
        if (col.progresoPatron) {
            actualizarProgresoPatron(col.id, col.progresoPatron, col.progresoExcluir);
        } else if (titulosFijosDe(col.id)) {
            actualizarProgresoTitulos(col.id, titulosFijosDe(col.id));
        } else if (col.progresoCategoria) {
            actualizarProgresoCategoria(col.id, col.progresoCategoria);
        } else if (!col.esContenedor) {
            // Estas colecciones (ej. Arkhamverse, LEGO DC) guardan sus ítems
            // "adentro" de la propia ficha (col.peliculas), no repartidos en
            // listaMedia. El progreso se calcula contando tarjetas ya
            // dibujadas en su grilla — pero esas tarjetas normalmente recién
            // se dibujan la primera vez que se abre la ficha. Sin este
            // paso, la tarjeta del hub queda pisada en 0% para siempre,
            // aunque el usuario ya haya marcado cosas como vistas/jugadas.
            asegurarPeliculasRenderizadas(col);
            if (col.peliculas.length > 0) {
                aplicarVistosGuardados(document.getElementById(`grilla-${col.id}`));
            }
            actualizarProgresoColeccion(col.id);
        }
    });
}

