function obtenerFilmografiaGrillaAuxiliar(nombre) {
    return filmografiasGrilla[normalizarTextoJuego(nombre)] || [];
}

function buscarColeccionPorNombre(nombreBuscado) {
    const normalizado = normalizarTextoJuego(nombreBuscado);
    return colecciones.find(c => normalizarTextoJuego(c.titulo) === normalizado);
}

// Devuelve la lista de títulos de la filmografía de una cartilla, sin importar
// si están embebidos en "peliculas" (como Tarantino) o repartidos en
// listaMedia bajo su propia categoría (como Nolan, Fincher, Spielberg,
// Ryan Gosling, Julia Roberts, etc.)
function obtenerFilmografiaColeccion(coleccionId) {
    const col = colecciones.find(c => c.id === coleccionId);
    if (!col) return [];
    const titulos = [];
    if (col.peliculas && col.peliculas.length > 0) {
        titulos.push(...col.peliculas.map(p => p.titulo));
    }
    if (col.progresoCategoria) {
        titulos.push(...listaMedia.filter(i => i.categoria === col.progresoCategoria).map(i => i.titulo));
    }
    return titulos;
}

// Devuelve la lista de títulos que definen una categoría de fila/columna,
// ya sea la filmografía de una cartilla de director ({tipo:"director"}) o
// una lista manual cargada a mano ({tipo:"lista"}).
function obtenerTitulosDeCategoria(categoria) {
    if (categoria.tipo === 'director') return obtenerFilmografiaColeccion(categoria.id);
    if (categoria.tipo === 'lista') return categoria.titulos || [];
    return [];
}

// Cruza la filmografía del actor resuelto en una celda contra una categoría
// (fila o columna) y devuelve los títulos en común. Si la categoría es de
// tipo "personas" (un roster directo, como "ganadores del Oscar", donde no
// nos importa en qué película ganaron sino simplemente si la persona está
// en la lista), devuelve una confirmación en vez de una lista de películas.
function calcularCoincidencias(nombreActor, categoria) {
    if (categoria.tipo === 'personas') {
        const normalizado = normalizarTextoJuego(nombreActor);
        const esMiembro = (categoria.nombres || []).some(n => normalizarTextoJuego(n) === normalizado);
        return esMiembro ? [categoria.etiquetaConfirmacion || '✓ Confirmado'] : [];
    }
    const coleccionActor = buscarColeccionPorNombre(nombreActor);
    const filmografiaReal = coleccionActor ? obtenerFilmografiaColeccion(coleccionActor.id) : [];
    const filmografiaAuxiliar = obtenerFilmografiaGrillaAuxiliar(nombreActor);
    const filmografiaActor = [...filmografiaReal, ...filmografiaAuxiliar].map(t => normalizarTextoJuego(t));
    const titulosCategoria = obtenerTitulosDeCategoria(categoria);
    return titulosCategoria.filter(t => filmografiaActor.includes(normalizarTextoJuego(t)));
}

function renderizarTablaGrilla() {
    const dataset = gridsDatasets[datasetIdActivoGrilla];
    const tabla = document.getElementById('tabla-grilla-juego');
    if (!dataset || !tabla) return;
    tabla.innerHTML = '';

    tabla.insertAdjacentHTML('beforeend', '<div class="celda-esquina"></div>');
    dataset.columnas.forEach(col => {
        const contenidoHeader = col.logo
            ? `<img src="${col.logo}" alt="${col.nombre}" class="logo-header-grilla">`
            : col.nombre;
        tabla.insertAdjacentHTML('beforeend', `<div class="celda-header-columna">${contenidoHeader}</div>`);
    });

    dataset.filas.forEach((fila, filaIdx) => {
        const contenidoHeaderFila = fila.logo
            ? `<img src="${fila.logo}" alt="${fila.nombre}" class="logo-header-grilla">`
            : fila.nombre;
        tabla.insertAdjacentHTML('beforeend', `<div class="celda-header-fila">${contenidoHeaderFila}</div>`);
        dataset.columnas.forEach((col, colIdx) => {
            const clave = `${filaIdx}-${colIdx}`;
            const celda = document.createElement('div');
            celda.className = 'celda-juego';
            celda.dataset.fila = filaIdx;
            celda.dataset.columna = colIdx;

            const resuelta = celdasResueltasGrilla[clave];
            if (resuelta) {
                celda.classList.add('resuelta');
                pintarCeldaResuelta(celda, resuelta, fila, col);
                celda.addEventListener('click', () => alternarVistaCeldaResuelta(celda, resuelta, fila, col));
            } else {
                celda.innerHTML = '<span class="signo-interrogacion">?</span>';
                if (celdasCandidatasGrilla.some(c => c.fila === filaIdx && c.columna === colIdx)) {
                    celda.classList.add('candidata');
                }
                celda.addEventListener('click', () => clickCeldaLibreGrilla(filaIdx, colIdx));
            }
            tabla.appendChild(celda);
        });
    });
}

// Dibuja el estado "foto" de una celda ya resuelta: la foto del actor si la
// encontramos reutilizada de su cartilla, o si no el check + nombre de siempre.
function pintarCeldaResuelta(celda, resuelta, fila, col) {
    celda.classList.remove('mostrando-coincidencias');
    if (resuelta.foto) {
        celda.innerHTML = `
            <img src="${resuelta.foto}" alt="${resuelta.nombreMostrado}" style="width:100%; height:70%; object-fit:cover; object-position:center 15%; border-radius:6px 6px 0 0;">
            <span class="nombre-celda-resuelta">${resuelta.nombreMostrado}</span>
        `;
    } else {
        celda.innerHTML = `<span class="check-celda-resuelta">✅</span><span class="nombre-celda-resuelta">${resuelta.nombreMostrado}</span>`;
    }
}

// Alterna entre mostrar la foto y mostrar la lista de en qué títulos
// coincide ese actor con la fila y con la columna.
function alternarVistaCeldaResuelta(celda, resuelta, fila, col) {
    if (celda.classList.contains('mostrando-coincidencias')) {
        pintarCeldaResuelta(celda, resuelta, fila, col);
        return;
    }
    celda.classList.add('mostrando-coincidencias');
    const filaTexto = resuelta.coincidenciasFila.length > 0 ? resuelta.coincidenciasFila.join(', ') : '(sin datos cargados)';
    const colTexto = resuelta.coincidenciasColumna.length > 0 ? resuelta.coincidenciasColumna.join(', ') : '(sin datos cargados)';
    celda.innerHTML = `
        <div class="lista-coincidencias-celda">
            <strong>${fila.nombre}:</strong> ${filaTexto}<br><br>
            <strong>${col.nombre}:</strong> ${colTexto}
        </div>
    `;
}

// Click en una celda todavía libre. Si hay un nombre pendiente (porque
// servía para más de una celda) y esta celda es una de las candidatas
// iluminadas, la resuelve ahí. Si no hay nada pendiente, no hace nada:
// el juego ahora se juega escribiendo el nombre directamente, no
// preseleccionando la celda.
function clickCeldaLibreGrilla(filaIdx, colIdx) {
    if (grillaTerminada) return;
    if (!nombrePendienteGrilla) return;
    const esCandidata = celdasCandidatasGrilla.some(c => c.fila === filaIdx && c.columna === colIdx);
    if (!esCandidata) return;
    resolverCeldaGrilla(filaIdx, colIdx, nombrePendienteGrilla);
}

function actualizarContadorGrilla() {
    const contador = document.getElementById('contador-grilla');
    if (!contador) return;
    const resueltas = Object.keys(celdasResueltasGrilla).length;
    if (modoInfinitoGrilla) {
        contador.textContent = `${resueltas}/9 · ${erroresGrilla} errores (intentos infinitos)`;
    } else {
        contador.textContent = `${resueltas}/9 · ${erroresGrilla} errores (máx. ${MAX_ERRORES_GRILLA})`;
    }
}

// Busca, entre todas las celdas TODAVÍA NO resueltas, en cuáles el nombre
// escrito es una respuesta válida. Ya no hace falta tocar una celda antes
// de escribir: si el nombre sirve para una sola celda libre, se resuelve
// sola; si sirve para más de una, se iluminan esas celdas y el jugador
// elige en cuál ponerla (no se puede repetir una respuesta usada).
// Devuelve true si el actor (ya resuelto a su nombre canónico) tiene algo
// en su filmografía que cumpla esta categoría (fila o columna).
function actorCumpleCategoria(nombreMostrado, categoria) {
    if (categoria.tipo === 'personas') {
        const normalizado = normalizarTextoJuego(nombreMostrado);
        return (categoria.nombres || []).some(n => normalizarTextoJuego(n) === normalizado);
    }
    const coleccionActor = buscarColeccionPorNombre(nombreMostrado);
    const filmografiaReal = coleccionActor ? obtenerFilmografiaColeccion(coleccionActor.id) : [];
    const filmografiaAuxiliar = obtenerFilmografiaGrillaAuxiliar(nombreMostrado);
    const filmografiaActor = [...filmografiaReal, ...filmografiaAuxiliar].map(t => normalizarTextoJuego(t));
    const titulosCategoria = obtenerTitulosDeCategoria(categoria);
    return titulosCategoria.some(t => filmografiaActor.includes(normalizarTextoJuego(t)));
}

// Intenta reconocer a quién se refiere lo que escribió el jugador: primero
// busca una cartilla real de Actor/Director (mejor escrita, trae foto), y
// si no existe, busca en la filmografía auxiliar de Grillas. Devuelve null
// si no lo reconoce en ninguna de las dos fuentes.
function resolverNombreJugadorGrilla(textoIngresado) {
    const coleccionActor = buscarColeccionPorNombre(textoIngresado);
    if (coleccionActor) return { nombreMostrado: coleccionActor.titulo, foto: coleccionActor.poster };
    const normalizado = normalizarTextoJuego(textoIngresado);
    if (filmografiasGrilla[normalizado]) return { nombreMostrado: capitalizarNombre(normalizado), foto: null };
    return null;
}

function intentarAdivinarGrilla() {
    if (grillaTerminada) return;
    const dataset = gridsDatasets[datasetIdActivoGrilla];
    const input = document.getElementById('input-grilla');
    const mensaje = document.getElementById('mensaje-grilla');
    const textoIngresado = input.value.trim();
    if (!normalizarTextoJuego(textoIngresado)) return;

    const resuelto = resolverNombreJugadorGrilla(textoIngresado);
    if (!resuelto) {
        erroresGrilla++;
        mensaje.textContent = `❌ No encontré a "${textoIngresado}" en la base cargada.`;
        mensaje.className = 'mensaje-elenco error';
        actualizarContadorGrilla();
        input.value = '';
        input.focus();
        if (erroresGrilla >= MAX_ERRORES_GRILLA && !modoInfinitoGrilla) finalizarGrilla(false);
        return;
    }

    const normalizadoEncontrado = normalizarTextoJuego(resuelto.nombreMostrado);
    const yaUsado = Object.values(celdasResueltasGrilla).some(r => normalizarTextoJuego(r.nombreMostrado) === normalizadoEncontrado);
    if (yaUsado) {
        erroresGrilla++;
        mensaje.textContent = `❌ "${resuelto.nombreMostrado}" ya se usó en otra celda.`;
        mensaje.className = 'mensaje-elenco error';
        actualizarContadorGrilla();
        input.value = '';
        input.focus();
        if (erroresGrilla >= MAX_ERRORES_GRILLA && !modoInfinitoGrilla) finalizarGrilla(false);
        return;
    }

    const candidatas = [];
    for (let f = 0; f < dataset.filas.length; f++) {
        for (let c = 0; c < dataset.columnas.length; c++) {
            const clave = `${f}-${c}`;
            if (celdasResueltasGrilla[clave]) continue;
            if (actorCumpleCategoria(resuelto.nombreMostrado, dataset.filas[f]) && actorCumpleCategoria(resuelto.nombreMostrado, dataset.columnas[c])) {
                candidatas.push({ fila: f, columna: c });
            }
        }
    }

    if (candidatas.length === 0) {
        erroresGrilla++;
        mensaje.textContent = `❌ "${resuelto.nombreMostrado}" no cumple ninguna celda libre.`;
        mensaje.className = 'mensaje-elenco error';
        actualizarContadorGrilla();
        input.value = '';
        input.focus();
        if (erroresGrilla >= MAX_ERRORES_GRILLA && !modoInfinitoGrilla) {
            finalizarGrilla(false);
        }
        return;
    }

    if (candidatas.length === 1) {
        input.value = '';
        resolverCeldaGrilla(candidatas[0].fila, candidatas[0].columna, resuelto.nombreMostrado);
        return;
    }

    // Ambiguo: hay más de una celda libre donde esta persona cumple fila+columna
    nombrePendienteGrilla = resuelto.nombreMostrado;
    celdasCandidatasGrilla = candidatas;
    document.querySelectorAll('#tabla-grilla-juego .celda-juego').forEach(celda => {
        const f = parseInt(celda.dataset.fila);
        const c = parseInt(celda.dataset.columna);
        const esCandidata = candidatas.some(cand => cand.fila === f && cand.columna === c);
        celda.classList.toggle('candidata', esCandidata);
    });
    mensaje.textContent = `🤔 "${resuelto.nombreMostrado}" sirve para ${candidatas.length} celdas — tocá en cuál la ponés.`;
    mensaje.className = 'mensaje-elenco';
    input.value = '';
    ocultarSugerenciasGrilla();
}

// Resuelve efectivamente una celda con el nombre ya validado (llamado tanto
// cuando hay una sola opción posible, como cuando el jugador elige entre
// varias celdas candidatas iluminadas).
function resolverCeldaGrilla(filaIdx, colIdx, nombreMostrado) {
    const dataset = gridsDatasets[datasetIdActivoGrilla];
    const clave = `${filaIdx}-${colIdx}`;
    const filaCategoria = dataset.filas[filaIdx];
    const colCategoria = dataset.columnas[colIdx];
    const coleccionActor = buscarColeccionPorNombre(nombreMostrado);
    const mensaje = document.getElementById('mensaje-grilla');

    celdasResueltasGrilla[clave] = {
        nombreMostrado: nombreMostrado,
        foto: coleccionActor ? coleccionActor.poster : null,
        coincidenciasFila: calcularCoincidencias(nombreMostrado, filaCategoria),
        coincidenciasColumna: calcularCoincidencias(nombreMostrado, colCategoria)
    };
    if (mensaje) {
        mensaje.textContent = `✅ ¡${nombreMostrado}!`;
        mensaje.className = 'mensaje-elenco exito';
    }

    nombrePendienteGrilla = null;
    celdasCandidatasGrilla = [];
    renderizarTablaGrilla();
    actualizarContadorGrilla();

    if (Object.keys(celdasResueltasGrilla).length === 9) {
        finalizarGrilla(true);
    }
}

function finalizarGrilla(gano) {
    grillaTerminada = true;
    nombrePendienteGrilla = null;
    celdasCandidatasGrilla = [];
    document.querySelectorAll('#tabla-grilla-juego .celda-juego.candidata').forEach(c => c.classList.remove('candidata'));
    const input = document.getElementById('input-grilla');
    const btnAdivinar = document.getElementById('btn-adivinar-grilla');
    if (input) input.disabled = true;
    if (btnAdivinar) btnAdivinar.disabled = true;

    const mensaje = document.getElementById('mensaje-grilla');
    if (gano) {
        mensaje.textContent = `🏆 ¡Completaste la grilla con ${erroresGrilla} errores!`;
        mensaje.className = 'mensaje-elenco victoria';
    } else {
        mensaje.textContent = `💀 Llegaste al máximo de errores. Se acabó el intento.`;
        mensaje.className = 'mensaje-elenco error';
    }
}


