const CON_COLORES = ['amarillo', 'verde', 'azul', 'violeta'];
const CON_EMOJI = { amarillo: '🟨', verde: '🟩', azul: '🟦', violeta: '🟪' };
const CON_NIVEL_TXT = { facil: 'Fácil', medio: 'Medio', dificil: 'Difícil' };
let conNivel = (function () { try { const n = localStorage.getItem('conexiones-nivel'); return ['facil', 'medio', 'dificil'].includes(n) ? n : 'medio'; } catch (e) { return 'medio'; } })();
let conModo = 'diaria';
let conGruposCache = null;
let conPuzzle = null;      // { grupos: [{titulo, color, miembros:[{nombre, imagen}]}], fichas: [{id, nombre, imagen, g}] }
let conOrden = [];
let conSeleccion = [];
let conResueltos = [];
let conErrores = 0;
let conIntentos = [];      // cada intento: lista de índices de grupo de las 4 fichas
let conTerminado = false;

function conNorm(x) { return String(x).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, ''); }

const CON_GENERICAS = new Set(['hombre', 'mujer', 'doctor', 'lady', 'captain', 'capitan', 'spider', 'iron', 'black', 'white', 'dark', 'king', 'queen', 'mister', 'agent', 'agente', 'woman', 'girl', 'from', 'with']);
// Palabras "con identidad" del nombre completo (incluye lo que va entre paréntesis): sirven para detectar al mismo personaje con dos nombres.
function conTokens(n) {
    return String(n).split(/[^A-Za-zÀ-ÿ0-9']+/).map(conNorm).filter(t => t.length >= 4 && !CON_GENERICAS.has(t));
}
function conMismoPersonaje(a, b) {
    const ta = conTokens(a);
    return conTokens(b).some(t => ta.includes(t));
}

function conNombreCorto(n) {
    const partes = String(n).split(' / ');
    const base = (/^Agent(e)? (of|de) /i.test(partes[0]) && partes[1]) ? partes[1] : partes[0];
    return base.split(' (')[0].trim();
}

function conFechaSemilla(extra) {
    const [a, m, d] = wordleFechaHoy().split('-').map(Number);
    return a * 10000 + m * 100 + d + extra;
}

function conRng(semilla) {
    let s = semilla >>> 0;
    return () => { s = (s * 1664525 + 1013904223) % 4294967296; return s / 4294967296; };
}

function conBarajar(arr, rng) {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(rng() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
}

function conConstruirGrupos() {
    if (conGruposCache) return conGruposCache;
    const nivelDe = { facil: 0, medio: 1, dificil: 2 };
    const grupos = [];
    // 1) Equipos del Wordle: miembros con su nivel de fama.
    const porEquipo = {};
    WORDLE_PALABRAS.forEach(p => {
        const k = p.universo + '|' + p.equipo;
        (porEquipo[k] = porEquipo[k] || { titulo: p.equipo, universo: p.universo, miembros: [] });
        const nombre = conNombreCorto(p.nombre);
        if (porEquipo[k].miembros.some(m => conMismoPersonaje(m.completo, p.nombre) || conNorm(m.nombre) === conNorm(nombre))) return;
        porEquipo[k].miembros.push({ nombre, completo: p.nombre, nivel: nivelDe[wordleNivelDe(p)], imagen: imagenDePersonaje(p.palabra) });
    });
    Object.values(porEquipo).forEach(g => {
        const n0 = g.miembros.filter(m => m.nivel === 0).length;
        const n1 = g.miembros.filter(m => m.nivel <= 1).length;
        if (g.miembros.length >= 4) grupos.push({ titulo: g.titulo, universo: g.universo, origen: 'equipo', miembros: g.miembros, aptoFacil: n0 >= 4, aptoMedio: n1 >= 4 });
    });
    // 2) Catálogos de Marvel por tipo.
    const famosos = new Set(WORDLE_PALABRAS.filter(p => wordleNivelDe(p) !== 'dificil').map(p => p.palabra));
    const esFamoso = (m) => (m.nombre + ' ' + (m.real || '')).split(/[^A-Za-zÀ-ÿ]+/).some(t => famosos.has(conNorm(t)));
    const etiqueta = { 'Villano': 'Villanos de', 'Héroe': 'Héroes de', 'Aliado': 'Aliados de', 'Antihéroe': 'Antihéroes de' };
    CON_CATALOGOS.forEach(cat => {
        let lista = [];
        try { lista = cat.lista(); } catch (e) { return; }
        ['Villano', 'Héroe', 'Aliado', 'Antihéroe'].filter(t => !cat.soloTipos || cat.soloTipos.includes(t)).forEach(tipo => {
            const miembros = [];
            lista.filter(x => x.tipo === tipo).forEach(x => {
                const nombre = conNombreCorto(x.nombre);
                if (nombre.length > 24 || /^(the|el|la|los) /i.test(nombre)) return;
                if (miembros.some(m => conNorm(m.nombre) === conNorm(nombre) || conMismoPersonaje(m.completo, x.nombre + ' ' + (x.real || '').split(' - ')[0]))) return;
                const m = { nombre, completo: x.nombre + ' ' + (x.real || '').split(' - ')[0], real: x.real, imagen: null };
                m.nivel = esFamoso(m) ? 1 : 2;
                miembros.push(m);
            });
            if (miembros.length >= 4) {
                const nMedio = miembros.filter(m => m.nivel <= 1).length;
                grupos.push({ titulo: etiqueta[tipo] + ' ' + cat.clave, universo: 'Marvel', origen: 'catalogo', miembros, aptoFacil: false, aptoMedio: cat.nivel === 'medio' && nMedio >= 4 });
            }
        });
    });
    // 3) Grupos temáticos armados a mano.
    CON_TEMAS.forEach(t => {
        const miembros = t.m.map(x => ({ nombre: x[0], completo: x[0] + ' ' + (x[2] || ''), nivel: x[1], imagen: null }));
        grupos.push({
            titulo: t.t, universo: t.u, origen: 'tema', miembros, incompat: t.incompat || [],
            aptoFacil: miembros.filter(m => m.nivel === 0).length >= 4,
            aptoMedio: miembros.filter(m => m.nivel <= 1).length >= 4
        });
    });
    conGruposCache = grupos;
    return grupos;
}

function conGenerar(nivel, rng) {
    const todos = conConstruirGrupos();
    const maxNivel = nivel === 'facil' ? 0 : nivel === 'medio' ? 1 : 2;
    let aptos = todos.filter(g => nivel === 'facil' ? g.aptoFacil : nivel === 'medio' ? (g.aptoMedio || g.aptoFacil) : true);
    for (let intento = 0; intento < 300; intento++) {
        const elegidos = [];
        const nombresUsados = [];
        for (const g of conBarajar(aptos, rng)) {
            if (elegidos.length === 4) break;
            if (elegidos.some(e => e.titulo === g.titulo)) continue;
            if (elegidos.some(e => e.incompat.includes(g.titulo) || (g.incompat || []).includes(e.titulo))) continue;
            if (nivel === 'dificil' && g.universo !== 'Mixto') {
                const ref = elegidos.find(e => e.universo !== 'Mixto');
                if (ref && ref.universo !== g.universo) continue;
            }
            const permitidos = g.miembros.filter(m => m.nivel <= maxNivel && !nombresUsados.some(u => conMismoPersonaje(u, m.completo) || conNorm(u) === conNorm(m.completo)));
            if (permitidos.length < 4) continue;
            const ms = conBarajar(permitidos, rng).slice(0, 4);
            elegidos.push({ titulo: g.titulo, universo: g.universo, incompat: g.incompat || [], miembros: ms, dif: ms.reduce((a, m) => a + m.nivel, 0) / 4 });
            ms.forEach(m => nombresUsados.push(m.completo));
        }
        if (elegidos.length === 4) {
            elegidos.sort((a, b) => a.dif - b.dif);
            const grupos = elegidos.map((g, i) => ({ titulo: g.titulo, color: CON_COLORES[i], miembros: g.miembros.map(m => ({ nombre: m.nombre, imagen: m.imagen })) }));
            const fichas = [];
            grupos.forEach((g, gi) => g.miembros.forEach(m => fichas.push({ id: fichas.length, nombre: m.nombre, imagen: m.imagen, g: gi })));
            return { grupos, fichas };
        }
    }
    return null;
}

function conClaveLocal() { return 'conexiones-dia-' + conNivel; }

function conGuardarLocal() {
    if (conModo !== 'diaria' || !conPuzzle) return;
    try {
        localStorage.setItem(conClaveLocal(), JSON.stringify({ fecha: wordleFechaHoy(), puzzle: conPuzzle, orden: conOrden, resueltos: conResueltos, errores: conErrores, intentos: conIntentos, terminado: conTerminado }));
    } catch (e) {}
}

function conCargarLocal() {
    try {
        const g = JSON.parse(localStorage.getItem(conClaveLocal()) || 'null');
        if (g && g.fecha === wordleFechaHoy() && g.puzzle && Array.isArray(g.orden)) return g;
    } catch (e) {}
    return null;
}

function conMensaje(texto, tipo) {
    const m = document.getElementById('con-mensaje');
    if (!m) return;
    m.textContent = texto || '';
    m.className = 'mensaje-elenco' + (tipo ? ' ' + tipo : '');
}

function conDibujar() {
    const cont = document.getElementById('con-grilla');
    if (!cont || !conPuzzle) return;
    cont.innerHTML = '';
    conResueltos.forEach(gi => {
        const g = conPuzzle.grupos[gi];
        const b = document.createElement('div');
        b.className = 'con-banda con-' + g.color;
        b.innerHTML = '<strong></strong><span></span>';
        b.querySelector('strong').textContent = g.titulo;
        b.querySelector('span').textContent = g.miembros.map(m => m.nombre).join(', ');
        cont.appendChild(b);
    });
    const resto = document.createElement('div');
    resto.className = 'con-fichas';
    conOrden.filter(id => !conResueltos.includes(conPuzzle.fichas[id].g)).forEach(id => {
        const f = conPuzzle.fichas[id];
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'con-ficha' + (conSeleccion.includes(id) ? ' seleccionada' : '');
        if (f.imagen) {
            const img = document.createElement('img');
            img.src = f.imagen;
            img.alt = '';
            img.loading = 'lazy';
            b.appendChild(img);
        }
        const sp = document.createElement('span');
        sp.textContent = f.nombre;
        b.appendChild(sp);
        b.addEventListener('click', () => conAlternar(id));
        resto.appendChild(b);
    });
    cont.appendChild(resto);
    const vidas = document.getElementById('con-vidas');
    if (vidas) vidas.textContent = '❤️'.repeat(4 - conErrores) + '🖤'.repeat(conErrores);
    const acciones = document.getElementById('con-acciones');
    if (acciones) acciones.classList.toggle('oculto', conTerminado);
    const enviar = document.getElementById('con-btn-enviar');
    if (enviar) enviar.disabled = conSeleccion.length !== 4;
}

function conAlternar(id) {
    if (conTerminado) return;
    const i = conSeleccion.indexOf(id);
    if (i >= 0) conSeleccion.splice(i, 1);
    else if (conSeleccion.length < 4) conSeleccion.push(id);
    conMensaje('');
    conDibujar();
}

function conTextoCompartir() {
    const titulo = conModo === 'diaria' ? 'Conexiones ' + wordleFechaHoy() : 'Conexiones (al azar)';
    const lineas = conIntentos.map(it => it.map(gi => CON_EMOJI[conPuzzle.grupos[gi].color]).join(''));
    return `${titulo} [${CON_NIVEL_TXT[conNivel]}] ${conResueltos.length === 4 && conErrores < 4 ? conErrores + ' errores' : 'X'}\n\n${lineas.join('\n')}`;
}

function conTerminar(gano) {
    conTerminado = true;
    if (!gano) {
        [0, 1, 2, 3].forEach(gi => { if (!conResueltos.includes(gi)) conResueltos.push(gi); });
    }
    conGuardarLocal();
    conDibujar();
    conMensaje(gano ? (conErrores === 0 ? '🎉 ¡Perfecto, sin errores!' : '🎉 ¡Lo resolviste!') : 'Se acabaron los intentos. Estos eran los grupos.', gano ? 'victoria' : 'error');
    const fin = document.getElementById('con-final');
    if (fin) fin.classList.remove('oculto');
}

function conEnviar() {
    if (conTerminado || conSeleccion.length !== 4) return;
    const gs = conSeleccion.map(id => conPuzzle.fichas[id].g);
    const clave = conSeleccion.slice().sort((a, b) => a - b).join(',');
    if (conIntentos.some(it => it.__clave === clave)) { conMensaje('Ya probaste esa combinación.', 'error'); return; }
    const registro = gs.slice();
    registro.__clave = clave;
    const cuenta = {};
    gs.forEach(g => { cuenta[g] = (cuenta[g] || 0) + 1; });
    const mejor = Math.max(...Object.values(cuenta));
    conIntentos.push(registro);
    if (mejor === 4) {
        conResueltos.push(gs[0]);
        conSeleccion = [];
        conMensaje('');
        if (conResueltos.length === 4) return conTerminar(true);
    } else {
        conErrores++;
        conSeleccion = [];
        conMensaje(mejor === 3 ? '¡Casi! Hay tres que van juntos.' : 'Esos no van juntos.', 'error');
        if (conErrores >= 4) return conTerminar(false);
    }
    conGuardarLocal();
    conDibujar();
}

function conIniciar(modo) {
    conModo = modo;
    conSeleccion = [];
    conResueltos = [];
    conErrores = 0;
    conIntentos = [];
    conTerminado = false;
    conPuzzle = null;
    document.getElementById('con-final').classList.add('oculto');
    document.querySelectorAll('.con-nivel').forEach(b => b.classList.toggle('activo', b.dataset.nivel === conNivel));
    const sub = document.getElementById('con-subtitulo');
    if (modo === 'diaria') {
        const g = conCargarLocal();
        if (g) {
            conPuzzle = g.puzzle; conOrden = g.orden; conResueltos = g.resueltos || []; conErrores = g.errores || 0; conIntentos = g.intentos || []; conTerminado = !!g.terminado;
        } else {
            conPuzzle = conGenerar(conNivel, conRng(conFechaSemilla({ facil: 1, medio: 2, dificil: 3 }[conNivel] * 7919)));
        }
        if (sub) sub.textContent = `Conexiones del día (${CON_NIVEL_TXT[conNivel]}): encontrá los 4 grupos de 4 personajes. Es la misma para todos. Tenés 4 errores.`;
    } else {
        conPuzzle = conGenerar(conNivel, Math.random);
        if (sub) sub.textContent = `Conexiones al azar (${CON_NIVEL_TXT[conNivel]}): no se guarda. Tenés 4 errores.`;
    }
    if (!conPuzzle) {
        if (sub) sub.textContent = 'No se pudo armar un tablero con los datos actuales.';
        document.getElementById('con-grilla').innerHTML = '';
        return;
    }
    if (!conOrden.length || modo !== 'diaria' || conPuzzle.fichas.length !== conOrden.length) {
        conOrden = conBarajar(conPuzzle.fichas.map(f => f.id), modo === 'diaria' ? conRng(conFechaSemilla(99)) : Math.random);
    }
    conMensaje('');
    conDibujar();
    if (conTerminado) {
        const gano = conResueltos.length === 4 && conErrores < 4;
        conMensaje(gano ? '🎉 Ya resolviste la de hoy.' : 'Hoy no salió. Estos eran los grupos.', gano ? 'victoria' : 'error');
        document.getElementById('con-final').classList.remove('oculto');
    }
}

const tarjetaConexiones = document.getElementById('tarjeta-conexiones');
if (tarjetaConexiones) {
    tarjetaConexiones.addEventListener('click', () => {
        conIniciar('diaria');
        cambiarSeccion(document.getElementById('seccion-conexiones'));
    });
}
const btnVolverJuegosDesdeCon = document.getElementById('btn-volver-juegos-desde-conexiones');
if (btnVolverJuegosDesdeCon) btnVolverJuegosDesdeCon.addEventListener('click', () => cambiarSeccion(document.getElementById('seccion-juegos')));
document.querySelectorAll('.con-nivel').forEach(b => b.addEventListener('click', () => {
    conNivel = b.dataset.nivel;
    try { localStorage.setItem('conexiones-nivel', conNivel); } catch (e) {}
    conIniciar('diaria');
}));
const conBtnEnviar = document.getElementById('con-btn-enviar');
if (conBtnEnviar) conBtnEnviar.addEventListener('click', conEnviar);
const conBtnMezclar = document.getElementById('con-btn-mezclar');
if (conBtnMezclar) conBtnMezclar.addEventListener('click', () => { conOrden = conBarajar(conOrden, Math.random); conDibujar(); conGuardarLocal(); });
const conBtnLimpiar = document.getElementById('con-btn-limpiar');
if (conBtnLimpiar) conBtnLimpiar.addEventListener('click', () => { conSeleccion = []; conDibujar(); });
const conBtnAzar = document.getElementById('con-btn-azar');
if (conBtnAzar) conBtnAzar.addEventListener('click', () => conIniciar('azar'));
const conBtnCompartir = document.getElementById('con-btn-compartir');
if (conBtnCompartir) {
    conBtnCompartir.addEventListener('click', () => {
        const texto = conTextoCompartir();
        const aviso = () => { conBtnCompartir.textContent = '¡Copiado!'; setTimeout(() => { conBtnCompartir.textContent = 'Copiar resultado'; }, 1800); };
        if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(texto).then(aviso).catch(() => {});
        else aviso();
    });
}

// ==========================================
// JUEGO "AHORCADO" (adiviná el nombre del personaje)
// ==========================================
// Se usa la lista de personajes del Wordle (WORDLE_PALABRAS) con el nombre completo (puede tener varias palabras).
// Solo se muestra la letra inicial del nombre completo (las iniciales de las demás palabras quedan ocultas).
const AH_MAX_ERRORES = 6;
const AH_TECLADO = ['qwertyuiop', 'asdfghjklñ', 'zxcvbnm'];
const AH_RE = /^[a-zñ]$/;
let ahAnimar = 0;            // número de la parte del muñeco que hay que dibujar con el lápiz
let ahAnimId = 0;
let ahIntroActivo = false;
let ahNuevaLetra = '';       // letra acertada en la última jugada: se escribe con el lápiz
let ahNivel = (function () { try { const n = localStorage.getItem('ahorcado-nivel'); return ['facil', 'medio', 'dificil'].includes(n) ? n : 'medio'; } catch (e) { return 'medio'; } })();
let ahModo = 'diaria';
let ahItem = null;           // { nombre, palabra, universo, equipo }
let ahLetras = new Set();    // letras jugadas (a-z)
let ahErrores = 0;
let ahTerminado = false;
let ahGano = false;
let ahPoolCache = {};

function ahNormLetra(c) {
    const x = String(c).toLowerCase();
    if (x === 'ñ') return 'ñ';
    return x.normalize('NFD').replace(/[̀-ͯ]/g, '');
}

// Elige el nombre "de personaje" a adivinar a partir de nombres como "Edward Nygma (Acertijo)" o "Oráculo (Barbara Gordon)".
const AH_NOMBRE_FIJO = { logan: 'Wolverine' };
function ahNombreDe(p) {
    if (AH_NOMBRE_FIJO[p.palabra]) return AH_NOMBRE_FIJO[p.palabra];
    let n = String(p.nombre);
    const m = n.match(/^(.*?)\s*\((.*)\)\s*$/);
    if (m) {
        const a = m[1].trim(), b = m[2].trim();
        const contiene = (t) => t.split(/[^A-Za-zÀ-ÿ0-9]+/).some(w => conNorm(w) === p.palabra);
        const pal = (t) => t.split(/\s+/).length;
        if (conNorm(a) === p.palabra) n = a;
        else if (contiene(a) && !contiene(b)) n = b;
        else if (contiene(b) && !contiene(a)) n = a;
        else n = pal(a) <= pal(b) ? a : b;
    }
    n = n.split(' / ')[0].replace(/\(.*?\)/g, '').replace(/,.*$/, '').replace(/\s+/g, ' ').trim();
    return n;
}

function ahPool(nivel) {
    if (ahPoolCache[nivel]) return ahPoolCache[nivel];
    const vistos = new Set();
    const lista = [];
    WORDLE_PALABRAS.forEach(p => {
        if (wordleNivelDe(p) !== nivel) return;
        const nombre = ahNombreDe(p);
        const letras = nombre.split('').filter(c => AH_RE.test(ahNormLetra(c))).length;
        if (letras < 4 || nombre.length > 26) return;
        const k = conNorm(nombre);
        if (vistos.has(k)) return;
        vistos.add(k);
        lista.push({ nombre, palabra: p.palabra, universo: p.universo, equipo: p.equipo });
    });
    ahPoolCache[nivel] = lista;
    return lista;
}

function ahLetrasDe(nombre) {
    return nombre.split('').map(ahNormLetra).filter(c => AH_RE.test(c));
}
function ahInicial() {
    const l = ahLetrasDe(ahItem.nombre);
    return l[0];
}
function ahReveladas() {
    const s = new Set(ahLetras);
    s.add(ahInicial());
    return s;
}
function ahCompleto() {
    const rev = ahReveladas();
    return ahLetrasDe(ahItem.nombre).every(c => rev.has(c));
}

function ahClaveLocal() { return 'ahorcado-dia-' + ahNivel; }
function ahGuardarLocal() {
    if (ahModo !== 'diaria' || !ahItem) return;
    try { localStorage.setItem(ahClaveLocal(), JSON.stringify({ fecha: wordleFechaHoy(), palabra: ahItem.palabra, letras: Array.from(ahLetras), errores: ahErrores, terminado: ahTerminado, gano: ahGano })); } catch (e) {}
}
function ahCargarLocal() {
    try {
        const g = JSON.parse(localStorage.getItem(ahClaveLocal()) || 'null');
        if (g && g.fecha === wordleFechaHoy() && g.palabra) return g;
    } catch (e) {}
    return null;
}
function ahStats() {
    try { return JSON.parse(localStorage.getItem('ahorcado-stats-' + ahNivel) || 'null') || { jugadas: 0, ganadas: 0, racha: 0, mejor: 0 }; } catch (e) { return { jugadas: 0, ganadas: 0, racha: 0, mejor: 0 }; }
}
function ahGuardarStats(gano) {
    const s = ahStats();
    s.jugadas++;
    if (gano) { s.ganadas++; s.racha++; s.mejor = Math.max(s.mejor, s.racha); } else { s.racha = 0; }
    try { localStorage.setItem('ahorcado-stats-' + ahNivel, JSON.stringify(s)); } catch (e) {}
}

function ahMensaje(t, tipo) {
    const m = document.getElementById('ah-mensaje');
    if (!m) return;
    m.textContent = t || '';
    m.className = 'mensaje-elenco' + (tipo ? ' ' + tipo : '');
}

// Traza un elemento SVG con el lápiz (animación simple). alTerminar se llama cuando termina el trazo.
function ahTrazar(el, dur, miId, alTerminar) {
    const lapiz = document.getElementById('ah-lapiz');
    let largo = 0;
    try { largo = el.getTotalLength(); } catch (e) { largo = 0; }
    if (!largo) { el.style.opacity = '1'; if (alTerminar) alTerminar(); else lapiz.style.display = 'none'; return; }
    el.style.strokeDasharray = largo;
    el.style.strokeDashoffset = largo;
    el.style.opacity = '1';
    lapiz.style.display = '';
    const t0 = performance.now();
    const paso = (ahora) => {
        if (miId !== ahAnimId) return;
        const f = Math.min(1, (ahora - t0) / dur);
        const e = f < 0.5 ? 2 * f * f : 1 - Math.pow(-2 * f + 2, 2) / 2;
        el.style.strokeDashoffset = String(largo * (1 - e));
        const pt = el.getPointAtLength(largo * e);
        const wob = Math.sin(f * 30) * 1.2;
        lapiz.setAttribute('transform', `translate(${pt.x.toFixed(1)},${(pt.y + wob).toFixed(1)}) rotate(-45) scale(0.62)`);
        if (f < 1) requestAnimationFrame(paso);
        else { el.style.strokeDasharray = ''; el.style.strokeDashoffset = ''; if (alTerminar) alTerminar(); else lapiz.style.display = 'none'; }
    };
    requestAnimationFrame(paso);
}

function ahMovimientoReducido() {
    return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
}

function ahGalloElems() { return Array.from(document.querySelectorAll('#ah-dibujo .ah-g')); }

// Intro: el lápiz dibuja la horca (hay un botón para saltear la animación).
function ahIntro() {
    const gs = ahGalloElems();
    const lapiz = document.getElementById('ah-lapiz');
    const btn = document.getElementById('ah-btn-saltear');
    if (!gs.length || !lapiz || ahMovimientoReducido() || typeof gs[0].getTotalLength !== 'function') { ahSaltearIntro(); return; }
    ahAnimId++;
    const miId = ahAnimId;
    ahIntroActivo = true;
    gs.forEach(g => { g.style.opacity = '0'; g.style.strokeDasharray = ''; g.style.strokeDashoffset = ''; });
    if (btn) btn.classList.remove('oculto');
    const durs = [350, 550, 400, 250];
    const siguiente = (i) => {
        if (miId !== ahAnimId) return;
        if (i >= gs.length) { ahIntroActivo = false; lapiz.style.display = 'none'; if (btn) btn.classList.add('oculto'); return; }
        ahTrazar(gs[i], durs[i] || 350, miId, () => siguiente(i + 1));
    };
    siguiente(0);
}

function ahSaltearIntro() {
    ahAnimId++;
    ahIntroActivo = false;
    const lapiz = document.getElementById('ah-lapiz');
    if (lapiz) lapiz.style.display = 'none';
    ahGalloElems().forEach(g => { g.style.opacity = '1'; g.style.strokeDasharray = ''; g.style.strokeDashoffset = ''; });
    const btn = document.getElementById('ah-btn-saltear');
    if (btn) btn.classList.add('oculto');
}

// Dibuja el muñeco: las partes ya hechas quedan fijas y la nueva se dibuja con un lápiz.
function ahDibujarMuneco() {
    const nueva = ahAnimar;
    ahAnimar = 0;
    if (ahIntroActivo) {
        if (!nueva) { for (let i = 1; i <= AH_MAX_ERRORES; i++) { const p = document.getElementById('ah-p' + i); if (p) p.style.opacity = ahErrores >= i ? '1' : '0'; } return; }
        ahSaltearIntro();
    }
    ahAnimId++;
    const miId = ahAnimId;
    const lapiz = document.getElementById('ah-lapiz');
    if (lapiz) lapiz.style.display = 'none';
    for (let i = 1; i <= AH_MAX_ERRORES; i++) {
        const p = document.getElementById('ah-p' + i);
        if (!p) continue;
        p.style.strokeDasharray = '';
        p.style.strokeDashoffset = '';
        p.style.opacity = ahErrores >= i ? '1' : '0';
    }
    const parte = nueva ? document.getElementById('ah-p' + nueva) : null;
    if (!parte || !lapiz || ahMovimientoReducido() || typeof parte.getTotalLength !== 'function') return;
    ahTrazar(parte, nueva === 1 ? 900 : 650, miId, null);
}

function ahDibujar() {
    const palabra = document.getElementById('ah-palabra');
    if (!palabra || !ahItem) return;
    const rev = ahReveladas();
    const fin = ahTerminado;
    palabra.innerHTML = '';
    let kEscribir = 0;
    ahItem.nombre.split(' ').forEach(pal => {
        const g = document.createElement('div');
        g.className = 'ah-grupo';
        pal.split('').forEach(c => {
            const n = ahNormLetra(c);
            const cel = document.createElement('div');
            cel.className = 'ah-celda';
            if (!AH_RE.test(n)) { cel.textContent = c; cel.classList.add('signo'); }
            else if (rev.has(n)) {
                const t = document.createElement('span');
                t.className = 'ah-letra-txt';
                t.textContent = c.toUpperCase();
                cel.appendChild(t);
                cel.classList.add('visible');
                if (n === ahNuevaLetra && !ahMovimientoReducido()) {
                    const d = (kEscribir * 0.5).toFixed(2) + 's';
                    kEscribir++;
                    cel.classList.add('escribiendo');
                    cel.style.setProperty('--d', d);
                    const lp = document.createElement('span');
                    lp.className = 'ah-lapiz-mini';
                    lp.innerHTML = '<svg viewBox="0 -3.5 47 7" width="30" height="8" aria-hidden="true"><polygon points="0,0 9,-3.5 9,3.5" fill="#e8c999"/><polygon points="0,0 3.4,-1.35 3.4,1.35" fill="#333"/><rect x="9" y="-3.5" width="29" height="7" fill="#f4c20d"/><rect x="38" y="-3.5" width="4" height="7" fill="#aaa"/><rect x="42" y="-3.5" width="5" height="7" rx="1.5" fill="#e57399"/></svg>';
                    cel.appendChild(lp);
                }
            }
            else if (fin) { cel.textContent = c.toUpperCase(); cel.classList.add('perdida'); }
            g.appendChild(cel);
        });
        palabra.appendChild(g);
    });
    ahNuevaLetra = '';
    ahDibujarMuneco();
    const vidas = document.getElementById('ah-vidas');
    if (vidas) vidas.textContent = '❤️'.repeat(Math.max(0, AH_MAX_ERRORES - ahErrores)) + '🖤'.repeat(Math.min(AH_MAX_ERRORES, ahErrores));
    const pista = document.getElementById('ah-pista');
    if (pista) pista.textContent = `Universo: ${ahItem.universo}` + (ahErrores >= 3 ? ` · Equipo: ${ahItem.equipo}` : ' · (la pista del equipo aparece al tercer error)');
    const tec = document.getElementById('ah-teclado');
    if (tec) {
        tec.innerHTML = '';
        AH_TECLADO.forEach(fila => {
            const f = document.createElement('div');
            f.className = 'wordle-fila-teclado';
            fila.split('').forEach(l => {
                const b = document.createElement('button');
                b.type = 'button';
                b.className = 'wordle-tecla';
                b.textContent = l.toUpperCase();
                const jugada = ahLetras.has(l) || l === ahInicial();
                if (jugada) {
                    const esta = ahLetrasDe(ahItem.nombre).includes(l);
                    b.classList.add(esta ? 'correcta' : 'ausente');
                    b.disabled = true;
                }
                if (ahTerminado) b.disabled = true;
                b.addEventListener('click', () => ahJugar(l));
                f.appendChild(b);
            });
            tec.appendChild(f);
        });
    }
}

function ahJugar(l) {
    if (ahTerminado || !ahItem || !AH_RE.test(l)) return;
    if (ahLetras.has(l) || l === ahInicial()) return;
    ahLetras.add(l);
    if (!ahLetrasDe(ahItem.nombre).includes(l)) { ahErrores++; ahAnimar = ahErrores; } else ahNuevaLetra = l;
    if (ahCompleto()) return ahTerminar(true);
    if (ahErrores >= AH_MAX_ERRORES) return ahTerminar(false);
    ahMensaje('');
    ahGuardarLocal();
    ahDibujar();
}

function ahTerminar(gano) {
    ahTerminado = true;
    ahGano = gano;
    if (ahModo === 'diaria') {
        const guardado = ahCargarLocal();
        if (!(guardado && guardado.terminado)) ahGuardarStats(gano);
    }
    ahGuardarLocal();
    ahMostrarFinal();
    ahDibujar();
}

function ahMostrarFinal() {
    ahMensaje(ahGano ? `🎉 ¡Era ${ahItem.nombre}! (${ahErrores} ${ahErrores === 1 ? 'error' : 'errores'})` : `Era: ${ahItem.nombre}`, ahGano ? 'victoria' : 'error');
    const fin = document.getElementById('ah-final');
    if (fin) fin.classList.remove('oculto');
    const img = document.getElementById('ah-final-img');
    if (img) {
        const u = typeof imagenDePersonaje === 'function' ? imagenDePersonaje(ahItem.palabra) : null;
        if (u) { img.src = u; img.classList.remove('oculto'); img.onerror = () => img.classList.add('oculto'); } else { img.classList.add('oculto'); }
    }
    const st = document.getElementById('ah-stats');
    if (st && ahModo === 'diaria') {
        const s = ahStats();
        st.textContent = `Partidas: ${s.jugadas} · Ganadas: ${s.ganadas} · Racha: ${s.racha} · Mejor racha: ${s.mejor}`;
    } else if (st) st.textContent = '';
}

function ahTextoCompartir() {
    const nom = { facil: 'Fácil', medio: 'Medio', dificil: 'Difícil' }[ahNivel];
    const dib = '🟥'.repeat(ahErrores) + '⬜'.repeat(AH_MAX_ERRORES - ahErrores);
    return `Ahorcado de Personajes (${nom}) ${ahGano ? '✅' : '❌'}\n${dib}\nEl Multiverso`;
}

function ahIniciar(modo) {
    ahModo = modo;
    ahLetras = new Set();
    ahErrores = 0;
    ahTerminado = false;
    ahGano = false;
    document.getElementById('ah-final').classList.add('oculto');
    document.querySelectorAll('.ah-nivel').forEach(b => b.classList.toggle('activo', b.dataset.nivel === ahNivel));
    const pool = ahPool(ahNivel);
    const sub = document.getElementById('ah-subtitulo');
    if (!pool.length) { if (sub) sub.textContent = 'No hay personajes para este nivel.'; return; }
    if (modo === 'diaria') {
        const g = ahCargarLocal();
        const nombreNivel = { facil: 'Fácil', medio: 'Medio', dificil: 'Difícil' }[ahNivel];
        if (g) {
            ahItem = pool.find(x => x.palabra === g.palabra) || null;
            if (ahItem) { ahLetras = new Set(g.letras || []); ahErrores = g.errores || 0; ahTerminado = !!g.terminado; ahGano = !!g.gano; }
        }
        if (!ahItem || !g) {
            const rng = conRng(conFechaSemilla({ facil: 11, medio: 13, dificil: 17 }[ahNivel] * 104729));
            ahItem = pool[Math.floor(rng() * pool.length)];
        }
        if (sub) sub.textContent = `Ahorcado del día (${nombreNivel}): adiviná el nombre del personaje. Solo se ve la letra inicial. Tenés ${AH_MAX_ERRORES} errores.`;
    } else {
        ahItem = pool[Math.floor(Math.random() * pool.length)];
        if (sub) sub.textContent = `Ahorcado al azar: no se guarda. Solo se ve la letra inicial. Tenés ${AH_MAX_ERRORES} errores.`;
    }
    ahMensaje('');
    ahDibujar();
    if (ahTerminado || ahErrores > 0 || ahLetras.size > 0) ahSaltearIntro(); else ahIntro();
    if (ahTerminado) ahMostrarFinal();
}

const tarjetaAhorcado = document.getElementById('tarjeta-ahorcado');
if (tarjetaAhorcado) {
    tarjetaAhorcado.addEventListener('click', () => {
        cambiarSeccion(document.getElementById('seccion-ahorcado'));
        ahIniciar('diaria');
    });
}
const btnVolverJuegosDesdeAh = document.getElementById('btn-volver-juegos-desde-ahorcado');
if (btnVolverJuegosDesdeAh) btnVolverJuegosDesdeAh.addEventListener('click', () => cambiarSeccion(document.getElementById('seccion-juegos')));
document.querySelectorAll('.ah-nivel').forEach(b => b.addEventListener('click', () => {
    ahNivel = b.dataset.nivel;
    try { localStorage.setItem('ahorcado-nivel', ahNivel); } catch (e) {}
    ahIniciar('diaria');
}));
const ahBtnSaltear = document.getElementById('ah-btn-saltear');
if (ahBtnSaltear) ahBtnSaltear.addEventListener('click', ahSaltearIntro);
const ahBtnAzar = document.getElementById('ah-btn-azar');
if (ahBtnAzar) ahBtnAzar.addEventListener('click', () => ahIniciar('azar'));
const ahBtnCompartir = document.getElementById('ah-btn-compartir');
if (ahBtnCompartir) {
    ahBtnCompartir.addEventListener('click', () => {
        const texto = ahTextoCompartir();
        const aviso = () => { ahBtnCompartir.textContent = '¡Copiado!'; setTimeout(() => { ahBtnCompartir.textContent = 'Copiar resultado'; }, 1800); };
        if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(texto).then(aviso).catch(() => {});
        else aviso();
    });
}
document.addEventListener('keydown', (e) => {
    const sec = document.getElementById('seccion-ahorcado');
    if (!sec || sec.classList.contains('oculto') || e.ctrlKey || e.metaKey || e.altKey) return;
    const l = ahNormLetra(e.key);
    if (AH_RE.test(l) && e.key.length === 1) ahJugar(l);
});

