// Niveles: intentos, ancho en "píxeles" del póster según cantidad de errores, y cuándo aparece la pista de la inicial (null = nunca)
const ADP_NIVELES = {
    facil:   { nombre: 'Fácil',   max: 6, px: [10, 16, 26, 42, 70, 120], pista: 1 },
    normal:  { nombre: 'Normal',  max: 5, px: [6, 9, 14, 24, 42],       pista: 2 },
    dificil: { nombre: 'Difícil', max: 4, px: [4, 6, 9, 14],            pista: null }
};
let adpNivel = (function () { try { const n = localStorage.getItem('adp-nivel'); return ADP_NIVELES[n] ? n : 'normal'; } catch (e) { return 'normal'; } })();
function adpMax() { return ADP_NIVELES[adpNivel].max; }
const ADP_TIPOS = { todo: 'Todo', 'Película': 'Películas', 'Serie': 'Series', 'Videojuego': 'Juegos' };
let adpTipo = (function () { try { const t = localStorage.getItem('adp-tipo'); return ADP_TIPOS[t] ? t : 'todo'; } catch (e) { return 'todo'; } })();
let adpModo = 'diaria';
let adpPoolCache = null;
let adpPool = [];
let adpItem = null;
let adpFallos = [];       // títulos adivinados mal (o 'saltear')
let adpTerminado = false;
let adpGano = false;
let adpImg = null;
let adpSug = [];
let adpSugIdx = -1;

function adpConstruirTodo() {
    if (adpPoolCache) return adpPoolCache;
    const vistos = new Set();
    const pool = [];
    const tipoPorFicha = {};
    const titulosPorFicha = {};
    (typeof listaMedia !== 'undefined' ? listaMedia : []).forEach(x => {
        if (!x.fichaTecnicaId) return;
        if (!tipoPorFicha[x.fichaTecnicaId]) tipoPorFicha[x.fichaTecnicaId] = x.tipo;
        (titulosPorFicha[x.fichaTecnicaId] = titulosPorFicha[x.fichaTecnicaId] || []).push(x.titulo);
    });
    document.querySelectorAll('section[id^="seccion-ficha-"]').forEach(sec => {
        const poster = sec.querySelector('.ficha-tecnica-poster');
        if (!poster || !poster.alt || !poster.getAttribute('src')) return;
        const k = conNorm(poster.alt);
        if (!k || vistos.has(k)) return;
        vistos.add(k);
        const idFicha = sec.id.replace('seccion-ficha-', '');
        const esJuego = [...sec.querySelectorAll('.puntuacion-fuente')].some(f => ['GameSpot', 'Vandal'].includes(f.textContent.trim()));
        let tipo = tipoPorFicha[idFicha] || ((esJuego || /^LEGO/i.test(poster.alt)) ? 'Videojuego' : 'Película');
        if (/^Serie/.test(tipo)) tipo = 'Serie';
        else if (tipo === 'Videojuego') tipo = 'Videojuego';
        else if (tipo === 'Película' || tipo === 'Animación') tipo = 'Película';
        else tipo = 'Otro';
        const titulo = poster.alt.trim();
        const alias = [];
        const kt = conNorm(titulo);
        [...(titulosPorFicha[idFicha] || []), ...(ADP_ALIAS[titulo] || [])].forEach(a => {
            const ka = conNorm(a);
            if (ka && ka !== kt && !alias.some(x => conNorm(x) === ka)) alias.push(a);
        });
        pool.push({ titulo, alias, poster: poster.getAttribute('src'), tipo });
    });
    adpPoolCache = pool;
    return pool;
}

function adpMensaje(t, tipo) {
    const m = document.getElementById('adp-mensaje');
    if (!m) return;
    m.textContent = t || '';
    m.className = 'mensaje-elenco' + (tipo ? ' ' + tipo : '');
}

function adpSufijoNivel() { return adpNivel === 'normal' ? '' : '-' + adpNivel; }
function adpClaveLocal() { return 'adp-dia-' + adpTipo + adpSufijoNivel(); }
function adpGuardarLocal() {
    if (adpModo !== 'diaria' || !adpItem) return;
    try { localStorage.setItem(adpClaveLocal(), JSON.stringify({ fecha: wordleFechaHoy(), titulo: adpItem.titulo, fallos: adpFallos, terminado: adpTerminado, gano: adpGano })); } catch (e) {}
}
function adpCargarLocal() {
    try { const g = JSON.parse(localStorage.getItem(adpClaveLocal()) || 'null'); if (g && g.fecha === wordleFechaHoy() && g.titulo) return g; } catch (e) {}
    return null;
}
function adpStats() {
    try { return JSON.parse(localStorage.getItem('adp-stats' + adpSufijoNivel()) || 'null') || { jugadas: 0, ganadas: 0, racha: 0, mejor: 0 }; } catch (e) { return { jugadas: 0, ganadas: 0, racha: 0, mejor: 0 }; }
}
function adpGuardarStats(gano) {
    const s = adpStats();
    s.jugadas++;
    if (gano) { s.ganadas++; s.racha++; s.mejor = Math.max(s.mejor, s.racha); } else s.racha = 0;
    try { localStorage.setItem('adp-stats' + adpSufijoNivel(), JSON.stringify(s)); } catch (e) {}
}

// Dibuja el póster pixelado (o completo). Solo se dibuja en un <canvas>: no se lee ningún píxel, así que funciona con imágenes de otros sitios.
function adpPintar() {
    const cv = document.getElementById('adp-canvas');
    if (!cv || !adpImg || !adpImg.naturalWidth) return;
    const W = 300, H = Math.round(300 * adpImg.naturalHeight / adpImg.naturalWidth);
    cv.width = W; cv.height = H;
    const ctx = cv.getContext('2d');
    if (adpTerminado) { ctx.imageSmoothingEnabled = true; ctx.drawImage(adpImg, 0, 0, W, H); return; }
    const pxs = ADP_NIVELES[adpNivel].px;
    const px = pxs[Math.min(adpFallos.length, pxs.length - 1)];
    const chico = document.createElement('canvas');
    chico.width = px; chico.height = Math.max(2, Math.round(px * adpImg.naturalHeight / adpImg.naturalWidth));
    chico.getContext('2d').drawImage(adpImg, 0, 0, chico.width, chico.height);
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(chico, 0, 0, W, H);
}

function adpDibujarEstado() {
    const intentos = document.getElementById('adp-intentos');
    if (intentos) intentos.textContent = '❤️'.repeat(Math.max(0, adpMax() - adpFallos.length)) + '🖤'.repeat(Math.min(adpMax(), adpFallos.length));
    const pista = document.getElementById('adp-pista');
    if (pista && adpItem) {
        const pal = adpItem.titulo.split(/\s+/).length;
        let t = `Tipo: ${adpItem.tipo}`;
        const desde = ADP_NIVELES[adpNivel].pista;
        if (desde !== null) {
            if (adpFallos.length >= desde) t += ` · ${pal} ${pal === 1 ? 'palabra' : 'palabras'} · empieza con "${adpItem.titulo[0].toUpperCase()}"`;
            else t += ` · (más pistas al ${desde === 1 ? 'primer' : 'segundo'} error)`;
        } else if (adpFallos.length >= adpMax() - 1) t += ` · ${pal} ${pal === 1 ? 'palabra' : 'palabras'}`;
        else t += ' · (sin más pistas hasta el último intento)';
        pista.textContent = t;
    }
    const hist = document.getElementById('adp-historial');
    if (hist) {
        hist.innerHTML = '';
        adpFallos.forEach(f => { const d = document.createElement('div'); d.className = 'adp-fallo'; d.textContent = '✗ ' + f; hist.appendChild(d); });
    }
    const ent = document.getElementById('adp-entrada');
    if (ent) { ent.disabled = adpTerminado; }
    const sal = document.getElementById('adp-btn-saltear');
    if (sal) sal.disabled = adpTerminado;
}

function adpMostrarFinal() {
    adpMensaje(adpGano ? `🎉 ¡Era ${adpItem.titulo}! (${adpFallos.length + 1}.º intento)` : `Era: ${adpItem.titulo}`, adpGano ? 'victoria' : 'error');
    const fin = document.getElementById('adp-final');
    if (fin) fin.classList.remove('oculto');
    const st = document.getElementById('adp-stats');
    if (st) { const s = adpStats(); st.textContent = `Partidas: ${s.jugadas} · Ganadas: ${s.ganadas} · Racha: ${s.racha} · Mejor racha: ${s.mejor}`; }
    adpOcultarSug();
}

function adpTerminar(gano) {
    adpTerminado = true;
    adpGano = gano;
    if (adpModo === 'diaria') {
        const g = adpCargarLocal();
        if (!(g && g.terminado)) adpGuardarStats(gano);
    }
    adpGuardarLocal();
    adpPintar();
    adpDibujarEstado();
    adpMostrarFinal();
}

function adpIntentar(titulo) {
    if (adpTerminado || !adpItem) return;
    if (conNorm(titulo) === conNorm(adpItem.titulo) || (adpItem.alias || []).some(a => conNorm(a) === conNorm(titulo))) return adpTerminar(true);
    if (adpFallos.some(f => conNorm(f) === conNorm(titulo))) { adpMensaje('Ya probaste ese título.', 'error'); return; }
    adpFallos.push(titulo);
    adpMensaje('');
    if (adpFallos.length >= adpMax()) return adpTerminar(false);
    adpGuardarLocal();
    adpPintar();
    adpDibujarEstado();
}

function adpSaltear() {
    if (adpTerminado || !adpItem) return;
    adpFallos.push('(salteado)');
    adpMensaje('');
    if (adpFallos.length >= adpMax()) return adpTerminar(false);
    adpGuardarLocal();
    adpPintar();
    adpDibujarEstado();
}

function adpOcultarSug() {
    const l = document.getElementById('adp-sugerencias');
    if (l) { l.classList.add('oculto'); l.innerHTML = ''; }
    adpSug = []; adpSugIdx = -1;
}

function adpActualizarSug() {
    const ent = document.getElementById('adp-entrada');
    const l = document.getElementById('adp-sugerencias');
    if (!ent || !l) return;
    const q = conNorm(ent.value);
    if (!q || adpTerminado) { adpOcultarSug(); return; }
    adpSug = [];
    adpPool.forEach(p => {
        if (conNorm(p.titulo).includes(q)) adpSug.push({ titulo: p.titulo });
        else { const a = (p.alias || []).find(x => conNorm(x).includes(q)); if (a) adpSug.push({ titulo: p.titulo, via: a }); }
    });
    adpSug = adpSug.slice(0, 8);
    adpSugIdx = adpSug.length ? 0 : -1;
    l.innerHTML = '';
    if (!adpSug.length) { l.classList.add('oculto'); return; }
    adpSug.forEach((p, i) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'adp-sug' + (i === 0 ? ' activa' : '');
        b.textContent = p.titulo;
        if (p.via) { const sm = document.createElement('small'); sm.textContent = ' · ' + p.via; sm.style.opacity = '.6'; b.appendChild(sm); }
        b.addEventListener('mousedown', (e) => { e.preventDefault(); ent.value = ''; adpOcultarSug(); adpIntentar(p.titulo); });
        l.appendChild(b);
    });
    l.classList.remove('oculto');
}

function adpCargarImagen(item, intento) {
    const cont = document.getElementById('adp-poster-cont');
    if (cont && cont.offsetHeight) cont.style.minHeight = cont.offsetHeight + 'px';
    adpImg = null;
    const img = new Image();
    img.onload = () => {
        if (adpItem !== item) return;
        adpImg = img;
        adpPintar();
        if (cont) requestAnimationFrame(() => { cont.style.minHeight = ''; });
    };
    img.onerror = () => {
        if (adpItem !== item) return;
        if (adpModo === 'azar' && intento < 5 && adpPool.length > 1) {
            adpItem = adpPool[Math.floor(Math.random() * adpPool.length)];
            adpFallos = [];
            adpDibujarEstado();
            adpCargarImagen(adpItem, intento + 1);
        } else {
            adpMensaje('No se pudo cargar el póster. Probá con otro.', 'error');
            if (cont) cont.style.minHeight = '';
        }
    };
    img.src = item.poster;
}

function adpIniciar(modo) {
    adpModo = modo;
    adpFallos = [];
    adpTerminado = false;
    adpGano = false;
    adpItem = null;
    adpOcultarSug();
    const ent = document.getElementById('adp-entrada');
    if (ent) ent.value = '';
    document.getElementById('adp-final').classList.add('oculto');
    document.querySelectorAll('.adp-tipo').forEach(b => b.classList.toggle('activo', b.dataset.tipo === adpTipo));
    document.querySelectorAll('.adp-nivel').forEach(b => b.classList.toggle('activo', b.dataset.nivel === adpNivel));
    const todas = adpConstruirTodo();
    adpPool = adpTipo === 'todo' ? todas : todas.filter(p => p.tipo === adpTipo);
    const sub = document.getElementById('adp-subtitulo');
    if (adpPool.length < 5) {
        if (sub) sub.textContent = 'Todavía no hay suficientes pósters de este tipo.';
        return;
    }
    if (modo === 'diaria') {
        const g = adpCargarLocal();
        if (g) {
            adpItem = adpPool.find(p => p.titulo === g.titulo) || null;
            if (adpItem) { adpFallos = g.fallos || []; adpTerminado = !!g.terminado; adpGano = !!g.gano; }
        }
        if (!adpItem) {
            const rng = conRng(conFechaSemilla(777 + Object.keys(ADP_TIPOS).indexOf(adpTipo) * 1013));
            adpItem = adpPool[Math.floor(rng() * adpPool.length)];
        }
        if (sub) sub.textContent = `Póster del día (${ADP_TIPOS[adpTipo]}, ${ADP_NIVELES[adpNivel].nombre}): adiviná la obra. Se va aclarando con cada error. Tenés ${adpMax()} intentos.`;
    } else {
        adpItem = adpPool[Math.floor(Math.random() * adpPool.length)];
        if (sub) sub.textContent = `Póster al azar (${ADP_TIPOS[adpTipo]}, ${ADP_NIVELES[adpNivel].nombre}): no se guarda. Tenés ${adpMax()} intentos.`;
    }
    adpMensaje('');
    adpDibujarEstado();
    adpCargarImagen(adpItem, 0);
    if (adpTerminado) adpMostrarFinal();
}

function adpTextoCompartir() {
    const usados = adpFallos.length + (adpGano ? 1 : 0);
    let linea = '';
    for (let i = 0; i < adpMax(); i++) linea += i < adpFallos.length ? '🟥' : (i === adpFallos.length && adpGano ? '🟩' : '⬜');
    return `Adiviná el póster (${ADP_TIPOS[adpTipo]}${adpNivel === 'normal' ? '' : ', ' + ADP_NIVELES[adpNivel].nombre}) ${adpGano ? '✅ ' + usados + '/' + adpMax() : '❌'}\n${linea}\nEl Multiverso`;
}

const tarjetaAdp = document.getElementById('tarjeta-adivinaposter');
if (tarjetaAdp) {
    tarjetaAdp.addEventListener('click', () => {
        cambiarSeccion(document.getElementById('seccion-adivinaposter'));
        adpIniciar('diaria');
    });
}
const btnVolverJuegosDesdeAdp = document.getElementById('btn-volver-juegos-desde-adivinaposter');
if (btnVolverJuegosDesdeAdp) btnVolverJuegosDesdeAdp.addEventListener('click', () => cambiarSeccion(document.getElementById('seccion-juegos')));
document.querySelectorAll('.adp-tipo').forEach(b => b.addEventListener('click', () => {
    adpTipo = b.dataset.tipo;
    try { localStorage.setItem('adp-tipo', adpTipo); } catch (e) {}
    adpIniciar('diaria');
}));
document.querySelectorAll('.adp-nivel').forEach(b => b.addEventListener('click', () => {
    adpNivel = b.dataset.nivel;
    try { localStorage.setItem('adp-nivel', adpNivel); } catch (e) {}
    adpIniciar('diaria');
}));
const adpEntrada = document.getElementById('adp-entrada');
if (adpEntrada) {
    adpEntrada.addEventListener('input', adpActualizarSug);
    adpEntrada.addEventListener('blur', () => setTimeout(adpOcultarSug, 120));
    adpEntrada.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            if (!adpSug.length) return;
            e.preventDefault();
            adpSugIdx = (adpSugIdx + (e.key === 'ArrowDown' ? 1 : -1) + adpSug.length) % adpSug.length;
            document.querySelectorAll('.adp-sug').forEach((b, i) => b.classList.toggle('activa', i === adpSugIdx));
        } else if (e.key === 'Enter') {
            e.preventDefault();
            let t = null;
            if (adpSug.length && adpSugIdx >= 0) t = adpSug[adpSugIdx].titulo;
            else { const q = conNorm(adpEntrada.value); const ex = adpPool.find(p => conNorm(p.titulo) === q || (p.alias || []).some(a => conNorm(a) === q)); if (ex) t = ex.titulo; }
            if (t) { adpEntrada.value = ''; adpOcultarSug(); adpIntentar(t); }
        } else if (e.key === 'Escape') adpOcultarSug();
    });
}
const adpBtnSaltear = document.getElementById('adp-btn-saltear');
if (adpBtnSaltear) adpBtnSaltear.addEventListener('click', adpSaltear);
const adpBtnAzar = document.getElementById('adp-btn-azar');
if (adpBtnAzar) adpBtnAzar.addEventListener('click', () => adpIniciar('azar'));
const adpBtnCompartir = document.getElementById('adp-btn-compartir');
if (adpBtnCompartir) {
    adpBtnCompartir.addEventListener('click', () => {
        const texto = adpTextoCompartir();
        const aviso = () => { adpBtnCompartir.textContent = '¡Copiado!'; setTimeout(() => { adpBtnCompartir.textContent = 'Copiar resultado'; }, 1800); };
        if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(texto).then(aviso).catch(() => {});
        else aviso();
    });
}

// ============================================================
// JUEGO "BINGO DEL MULTIVERSO" (cartón 5x5 + bolillero + 2 rivales CPU)
// ============================================================
const BG_FUENTES = { todo: 'Marvel y DC', marvel: 'Marvel', dc: 'DC', obras: 'Películas y series' };
const BG_MODOS = { linea: 'Línea', lleno: 'Cartón lleno' };
const BG_TOTAL = 75;
const BG_RIVALES = ['Nick Fury', 'Alfred', 'Rocket', 'Amanda Waller', 'Mayordomo de Stark', 'Oracle'];
const BG_LINEAS = (function () {
    const l = [];
    for (let i = 0; i < 5; i++) { l.push([0, 1, 2, 3, 4].map(j => i * 5 + j)); l.push([0, 1, 2, 3, 4].map(j => j * 5 + i)); }
    l.push([0, 6, 12, 18, 24]); l.push([4, 8, 12, 16, 20]);
    return l;
})();
let bgFuente = (function () { try { const t = localStorage.getItem('bg-fuente'); return BG_FUENTES[t] ? t : 'todo'; } catch (e) { return 'todo'; } })();
let bgModo = (function () { try { const t = localStorage.getItem('bg-modo'); return BG_MODOS[t] ? t : 'linea'; } catch (e) { return 'linea'; } })();
let bgPartida = 'diaria';
let bgItems = [];        // 75 elementos { n, u, img }
let bgOrden = [];        // orden en que salen (índices de bgItems)
let bgSalidas = 0;
let bgCarton = [];       // 25 índices (el 12 es -1 = libre)
let bgMarcas = [];       // 25 booleanos
let bgRivales = [];      // { nombre, carton, marcas }
let bgTerminado = false;
let bgGano = false;
let bgGanador = '';
let bgFalsos = 0;
let bgTimer = null;
let bgRngCpu = Math.random;

function bgPoolFuente() {
    const vistos = new Set();
    const out = [];
    const add = (n, u, img) => { const k = conNorm(n); if (!k || vistos.has(k)) return; vistos.add(k); out.push({ n, u, img: img || null }); };
    if (bgFuente === 'obras') {
        adpConstruirTodo().filter(p => p.tipo === 'Película' || p.tipo === 'Serie').forEach(p => { if (p.titulo.length <= 30) add(p.titulo, 'Obra', p.poster); });
    } else {
        WORDLE_PALABRAS.forEach(p => {
            if (bgFuente === 'marvel' && p.universo !== 'Marvel') return;
            if (bgFuente === 'dc' && p.universo !== 'DC') return;
            let img = null;
            try { img = imagenDePersonaje(p.palabra); } catch (e) {}
            add(ahNombreDe(p), p.universo, img);
        });
    }
    return out;
}

function bgLineaCompleta(marcas) { return BG_LINEAS.some(l => l.every(i => marcas[i])); }
function bgGanaCon(marcas) { return bgModo === 'lleno' ? marcas.every(Boolean) : bgLineaCompleta(marcas); }
function bgFaltan(marcas) {
    if (bgModo === 'lleno') return marcas.filter(m => !m).length;
    return Math.min(...BG_LINEAS.map(l => l.filter(i => !marcas[i]).length));
}
function bgSalio(idx) { for (let k = 0; k < bgSalidas; k++) if (bgOrden[k] === idx) return true; return false; }

function bgDetener() { if (bgTimer) { clearInterval(bgTimer); bgTimer = null; } const b = document.getElementById('bg-btn-auto'); if (b) b.textContent = '▶ Auto'; }

function bgMensaje(t, tipo) {
    const m = document.getElementById('bg-mensaje');
    if (!m) return;
    m.textContent = t || '';
    m.className = 'mensaje-elenco' + (tipo ? ' ' + tipo : '');
}

function bgClaveLocal() { return 'bingo-dia-' + bgFuente + '-' + bgModo; }
function bgStats() {
    try { return JSON.parse(localStorage.getItem('bingo-stats') || 'null') || { jugadas: 0, ganadas: 0, racha: 0, mejor: 0 }; } catch (e) { return { jugadas: 0, ganadas: 0, racha: 0, mejor: 0 }; }
}
function bgGuardarStats(gano, bolillas) {
    const s = bgStats();
    s.jugadas++;
    if (gano) { s.ganadas++; s.racha++; if (!s.mejor || bolillas < s.mejor) s.mejor = bolillas; } else s.racha = 0;
    try { localStorage.setItem('bingo-stats', JSON.stringify(s)); } catch (e) {}
}

function bgDibujarCarton() {
    const cont = document.getElementById('bg-carton');
    if (!cont) return;
    cont.innerHTML = '';
    'BINGO'.split('').forEach(l => { const d = document.createElement('div'); d.className = 'bg-letra'; d.textContent = l; cont.appendChild(d); });
    bgCarton.forEach((idx, i) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'bg-celda' + (idx === -1 ? ' libre' : '') + (bgMarcas[i] ? ' marcada' : '');
        b.dataset.pos = i;
        b.textContent = idx === -1 ? '★ LIBRE' : bgItems[idx].n;
        if (idx !== -1) b.classList.add('u-' + bgItems[idx].u.toLowerCase());
        b.addEventListener('click', () => bgMarcar(i));
        cont.appendChild(b);
    });
}

function bgDibujarRivales() {
    const c = document.getElementById('bg-rivales');
    if (!c) return;
    c.innerHTML = '';
    bgRivales.forEach(r => {
        const f = bgFaltan(r.marcas);
        const d = document.createElement('div');
        d.className = 'bg-rival' + (bgTerminado && bgGanador === r.nombre ? ' gano' : '');
        d.textContent = `🤖 ${r.nombre}: ${f === 0 ? '¡BINGO!' : 'le ' + (f === 1 ? 'falta 1' : 'faltan ' + f)}`;
        c.appendChild(d);
    });
}

function bgDibujarBola(animar) {
    const bola = document.getElementById('bg-bola');
    const num = document.getElementById('bg-bola-n');
    const hist = document.getElementById('bg-historial');
    if (num) num.textContent = `Bolilla ${bgSalidas} / ${BG_TOTAL}`;
    if (bola) {
        bola.innerHTML = '';
        bola.className = 'bg-bola';
        if (bgSalidas > 0) {
            const it = bgItems[bgOrden[bgSalidas - 1]];
            bola.classList.add('u-' + it.u.toLowerCase());
            if (it.img) { const im = document.createElement('img'); im.src = it.img; im.alt = ''; im.className = 'bg-bola-img'; im.referrerPolicy = 'no-referrer'; im.onerror = () => im.remove(); bola.appendChild(im); }
            const t = document.createElement('div'); t.className = 'bg-bola-nombre'; t.textContent = it.n; bola.appendChild(t);
            if (animar) { void bola.offsetWidth; bola.classList.add('bg-giro'); }
        } else {
            bola.textContent = '🎱';
        }
    }
    if (hist) {
        hist.innerHTML = '';
        for (let k = bgSalidas - 2; k >= Math.max(0, bgSalidas - 12); k--) {
            const s = document.createElement('span'); s.className = 'bg-chip'; s.textContent = bgItems[bgOrden[k]].n; hist.appendChild(s);
        }
    }
}

function bgActualizarBotones() {
    const sacar = document.getElementById('bg-btn-sacar'), bingo = document.getElementById('bg-btn-bingo'), auto = document.getElementById('bg-btn-auto');
    if (sacar) sacar.disabled = bgTerminado || bgSalidas >= BG_TOTAL;
    if (bingo) bingo.disabled = bgTerminado;
    if (auto) auto.disabled = bgTerminado;
}

function bgMarcar(i) {
    if (bgTerminado) return;
    const idx = bgCarton[i];
    if (idx === -1) return;
    const cel = document.querySelector(`.bg-celda[data-pos="${i}"]`);
    if (bgMarcas[i]) { bgMarcas[i] = false; if (cel) cel.classList.remove('marcada'); return; }
    if (!bgSalio(idx)) {
        bgMensaje('Esa todavía no salió del bolillero.', 'error');
        if (cel) { cel.classList.remove('bg-no'); void cel.offsetWidth; cel.classList.add('bg-no'); }
        return;
    }
    bgMarcas[i] = true;
    if (cel) cel.classList.add('marcada');
    bgMensaje('');
}

function bgTerminar(gano, ganador) {
    bgTerminado = true;
    bgGano = gano;
    bgGanador = ganador || (gano ? 'Vos' : '');
    bgDetener();
    if (bgPartida === 'diaria') {
        let previo = null;
        try { previo = JSON.parse(localStorage.getItem(bgClaveLocal()) || 'null'); } catch (e) {}
        if (!(previo && previo.fecha === wordleFechaHoy() && previo.terminado)) bgGuardarStats(gano, bgSalidas);
        try { localStorage.setItem(bgClaveLocal(), JSON.stringify({ fecha: wordleFechaHoy(), terminado: true, gano, bolillas: bgSalidas, ganador: bgGanador })); } catch (e) {}
    } else bgGuardarStats(gano, bgSalidas);
    bgMostrarFinal();
}

function bgMostrarFinal() {
    if (bgGano) bgMensaje(`🎉 ¡BINGO! Ganaste con ${bgSalidas} bolillas${bgFalsos ? ` (${bgFalsos} falsa${bgFalsos > 1 ? 's' : ''} alarma${bgFalsos > 1 ? 's' : ''})` : ''}.`, 'victoria');
    else if (bgGanador === 'Descalificado') bgMensaje('Te descalificaron por cantar bingo en falso 3 veces. 😬', 'error');
    else if (bgGanador) bgMensaje(`${bgGanador} cantó bingo antes que vos (bolilla ${bgSalidas}).`, 'error');
    else bgMensaje('Se acabó el bolillero sin ganador.', 'error');
    const fin = document.getElementById('bg-final');
    if (fin) fin.classList.remove('oculto');
    const st = document.getElementById('bg-stats');
    if (st) { const s = bgStats(); st.textContent = `Partidas: ${s.jugadas} · Ganadas: ${s.ganadas} · Racha: ${s.racha}` + (s.mejor ? ` · Mejor: ${s.mejor} bolillas` : ''); }
    bgDibujarRivales();
    bgActualizarBotones();
}

function bgSacar() {
    if (bgTerminado) return;
    // Si algún rival ya tenía bingo con la bolilla anterior, lo canta antes de que salga la siguiente
    const rival = bgRivales.find(r => bgGanaCon(r.marcas));
    if (rival) return bgTerminar(false, rival.nombre);
    if (bgSalidas >= BG_TOTAL) return bgTerminar(false, '');
    const idx = bgOrden[bgSalidas];
    bgSalidas++;
    bgRivales.forEach(r => { const p = r.carton.indexOf(idx); if (p !== -1 && bgRngCpu() < 0.88) r.marcas[p] = true; });  // los rivales a veces se distraen
    const auto = document.getElementById('bg-automarcar');
    if (auto && auto.checked) { const p = bgCarton.indexOf(idx); if (p !== -1) { bgMarcas[p] = true; const cel = document.querySelector(`.bg-celda[data-pos="${p}"]`); if (cel) cel.classList.add('marcada'); } }
    bgMensaje('');
    bgDibujarBola(true);
    bgDibujarRivales();
    bgActualizarBotones();
}

function bgCantar() {
    if (bgTerminado) return;
    if (bgGanaCon(bgMarcas)) return bgTerminar(true);
    bgFalsos++;
    if (bgFalsos >= 3) { bgTerminar(false, 'Descalificado'); return; }
    bgMensaje(`¡Falsa alarma! Todavía no tenés ${bgModo === 'lleno' ? 'el cartón lleno' : 'una línea'}. (${bgFalsos}/3 — a la tercera quedás afuera)`, 'error');
}

function bgAuto() {
    if (bgTimer) { bgDetener(); return; }
    const vel = parseInt((document.getElementById('bg-vel') || {}).value, 10) || 2500;
    const b = document.getElementById('bg-btn-auto');
    if (b) b.textContent = '⏸ Pausa';
    bgSacar();
    bgTimer = setInterval(() => {
        const sec = document.getElementById('seccion-bingo');
        if (!sec || sec.classList.contains('oculto') || bgTerminado) { bgDetener(); return; }
        bgSacar();
    }, vel);
}

function bgIniciar(partida) {
    bgDetener();
    bgPartida = partida;
    bgTerminado = false; bgGano = false; bgGanador = ''; bgFalsos = 0; bgSalidas = 0;
    document.getElementById('bg-final').classList.add('oculto');
    document.querySelectorAll('.bg-fuente').forEach(b => b.classList.toggle('activo', b.dataset.fuente === bgFuente));
    document.querySelectorAll('.bg-modo').forEach(b => b.classList.toggle('activo', b.dataset.modo === bgModo));
    const todos = bgPoolFuente();
    const sub = document.getElementById('bg-subtitulo');
    if (todos.length < BG_TOTAL) {
        // fuente chica: se usan todos los disponibles (mínimo para armar 3 cartones)
        if (todos.length < 40) { if (sub) sub.textContent = 'Todavía no hay suficientes elementos para esta categoría.'; return; }
    }
    const rng = partida === 'diaria'
        ? conRng(conFechaSemilla(4242 + Object.keys(BG_FUENTES).indexOf(bgFuente) * 911 + Object.keys(BG_MODOS).indexOf(bgModo) * 37))
        : conRng((Math.random() * 4294967296) >>> 0);
    bgRngCpu = conRng((conFechaSemilla(99) + (partida === 'diaria' ? Object.keys(BG_FUENTES).indexOf(bgFuente) * 7 + Object.keys(BG_MODOS).indexOf(bgModo) : Math.floor(Math.random() * 1e6))) >>> 0);
    bgItems = conBarajar(todos, rng).slice(0, BG_TOTAL);
    bgOrden = conBarajar(bgItems.map((_, i) => i), rng);
    const armar = () => { const c = conBarajar(bgItems.map((_, i) => i), rng).slice(0, 24); c.splice(12, 0, -1); return c; };
    bgCarton = armar();
    bgMarcas = bgCarton.map(i => i === -1);
    const nombres = conBarajar(BG_RIVALES, rng).slice(0, 2);
    bgRivales = nombres.map(n => { const c = armar(); return { nombre: n, carton: c, marcas: c.map(i => i === -1) }; });
    if (sub) sub.textContent = (partida === 'diaria' ? 'Bingo del día' : 'Bingo al azar') + ` (${BG_FUENTES[bgFuente]}, ${BG_MODOS[bgModo]}): marcá en tu cartón lo que va saliendo y cantá ¡BINGO! antes que tus rivales.`;
    bgMensaje('');
    bgDibujarCarton();
    bgDibujarBola(false);
    bgDibujarRivales();
    bgActualizarBotones();
    if (partida === 'diaria') {
        let g = null;
        try { g = JSON.parse(localStorage.getItem(bgClaveLocal()) || 'null'); } catch (e) {}
        if (g && g.fecha === wordleFechaHoy() && g.terminado) {
            // ya se jugó hoy: se muestra el resultado y el tablero como quedó
            bgSalidas = Math.min(BG_TOTAL, g.bolillas || 0);
            bgOrden.slice(0, bgSalidas).forEach(idx => { const p = bgCarton.indexOf(idx); if (p !== -1 && g.gano) bgMarcas[p] = true; bgRivales.forEach(r => { const q = r.carton.indexOf(idx); if (q !== -1) r.marcas[q] = true; }); });
            bgTerminado = true; bgGano = !!g.gano; bgGanador = g.ganador || '';
            bgDibujarCarton(); bgDibujarBola(false); bgMostrarFinal();
        }
    }
}

function bgTextoCompartir() {
    return `Bingo del Multiverso (${BG_FUENTES[bgFuente]}, ${BG_MODOS[bgModo]}) ${bgGano ? '🎉 ¡BINGO en ' + bgSalidas + ' bolillas!' : '❌ ' + (bgGanador ? 'Ganó ' + bgGanador : 'sin ganador')}\nEl Multiverso`;
}

