let indiceResaltadoSugerenciasGrilla = -1;

const inputGrilla = document.getElementById('input-grilla');
if (inputGrilla) {
    inputGrilla.addEventListener('keydown', (e) => {
        const cont = document.getElementById('sugerencias-grilla');
        const hayDropdownVisible = cont && !cont.classList.contains('oculto') && cont.children.length > 0;

        if (hayDropdownVisible && e.key === 'ArrowDown') {
            e.preventDefault();
            moverResaltadoSugerenciasGrilla(1);
            return;
        }
        if (hayDropdownVisible && e.key === 'ArrowUp') {
            e.preventDefault();
            moverResaltadoSugerenciasGrilla(-1);
            return;
        }
        if (e.key === 'Enter') {
            e.preventDefault();
            if (hayDropdownVisible && indiceResaltadoSugerenciasGrilla >= 0) {
                const items = cont.querySelectorAll('.sugerencia-item');
                const elegido = items[indiceResaltadoSugerenciasGrilla];
                if (elegido) {
                    inputGrilla.value = elegido.textContent;
                    ocultarSugerenciasGrilla();
                }
            }
            intentarAdivinarGrilla();
            return;
        }
        if (e.key === 'Escape') {
            ocultarSugerenciasGrilla();
        }
    });
}

// Mueve el resaltado de sugerencias con las flechas (delta: +1 abajo, -1 arriba),
// dando la vuelta en los extremos.
function moverResaltadoSugerenciasGrilla(delta) {
    const cont = document.getElementById('sugerencias-grilla');
    if (!cont) return;
    const items = cont.querySelectorAll('.sugerencia-item');
    if (items.length === 0) return;

    indiceResaltadoSugerenciasGrilla = (indiceResaltadoSugerenciasGrilla + delta + items.length) % items.length;
    items.forEach((item, i) => item.classList.toggle('resaltada', i === indiceResaltadoSugerenciasGrilla));
    const elegido = items[indiceResaltadoSugerenciasGrilla];
    if (elegido && elegido.scrollIntoView) elegido.scrollIntoView({ block: 'nearest' });
}

// ==========================================
// AUTOCOMPLETADO DEL INPUT DE GRILLAS
// ==========================================
// Pone en mayúscula cada palabra de una clave normalizada (ej. "chris
// pratt" -> "Chris Pratt"). No reconstruye acentos ni apóstrofes
// exactos, pero alcanza para mostrar una sugerencia legible.
function capitalizarNombre(claveNormalizada) {
    return claveNormalizada
        .split(' ')
        .map(palabra => palabra.charAt(0).toUpperCase() + palabra.slice(1))
        .join(' ');
}

// Junta, sin duplicar, los nombres de la filmografía auxiliar de Grillas
// con los de las cartillas reales de Actores/Directores del sitio. Se
// deduplica por nombre NORMALIZADO (sin importar mayúsculas/tildes), y
// cuando el mismo nombre existe en las dos fuentes, se prioriza el de la
// cartilla real porque ya tiene la escritura correcta (ej. "DiCaprio" con
// mayúscula en el medio, que la capitalización automática de la
// filmografía auxiliar no puede reconstruir bien).
function obtenerNombresParaSugerenciasGrilla() {
    const nombresPorClave = new Map();
    Object.keys(filmografiasGrilla).forEach(clave => {
        nombresPorClave.set(clave, capitalizarNombre(clave));
    });
    colecciones.forEach(c => {
        if (c.categoria === 'actores' || c.categoria === 'directores') {
            nombresPorClave.set(normalizarTextoJuego(c.titulo), c.titulo);
        }
    });
    Object.values(personajesGrilla).forEach(lista => {
        lista.forEach(personaje => {
            nombresPorClave.set(normalizarTextoJuego(personaje), personaje);
        });
    });
    return Array.from(nombresPorClave.values());
}

const listaNombresSugerenciasGrilla = obtenerNombresParaSugerenciasGrilla();

function mostrarSugerenciasGrilla(texto) {
    const cont = document.getElementById('sugerencias-grilla');
    if (!cont) return;
    indiceResaltadoSugerenciasGrilla = -1;
    const textoNormalizado = normalizarTextoJuego(texto);
    if (!textoNormalizado || textoNormalizado.length < 2) {
        ocultarSugerenciasGrilla();
        return;
    }
    const coincidencias = listaNombresSugerenciasGrilla
        .filter(nombre => normalizarTextoJuego(nombre).includes(textoNormalizado))
        .slice(0, 8);

    if (coincidencias.length === 0) {
        ocultarSugerenciasGrilla();
        return;
    }
    cont.innerHTML = coincidencias.map(nombre => `<div class="sugerencia-item">${nombre}</div>`).join('');
    cont.classList.remove('oculto');
    cont.querySelectorAll('.sugerencia-item').forEach(item => {
        item.addEventListener('mousedown', (e) => {
            // mousedown (no click) para que dispare ANTES del blur del input
            e.preventDefault();
            const input = document.getElementById('input-grilla');
            if (input) input.value = item.textContent;
            ocultarSugerenciasGrilla();
        });
    });
}

function ocultarSugerenciasGrilla() {
    const cont = document.getElementById('sugerencias-grilla');
    if (cont) { cont.classList.add('oculto'); cont.innerHTML = ''; }
    indiceResaltadoSugerenciasGrilla = -1;
}

if (inputGrilla) {
    inputGrilla.addEventListener('input', () => mostrarSugerenciasGrilla(inputGrilla.value));
    inputGrilla.addEventListener('blur', () => {
        // Pequeño delay para que el mousedown de una sugerencia alcance a procesarse primero
        setTimeout(ocultarSugerenciasGrilla, 150);
    });
}

